using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using MyFundex.BuildingBlocks.Abstractions;using MyFundex.BuildingBlocks.Domain;using MyFundex.BuildingBlocks.Persistence;using MyFundex.Contracts;
namespace MyFundex.Wallet;
public sealed class WalletAccount:EntityBase{public Guid WalletId{get;set;}public long FundedAccountInternalId{get;set;}public string CurrencyCode{get;set;}="INR";public string Status{get;set;}="Active";public decimal CachedAvailableBalance{get;set;}public decimal CachedWithdrawableBalance{get;set;}}
public sealed class LedgerTransaction:EntityBase{public Guid TransactionId{get;set;}public string TransactionType{get;set;}="";public string ReferenceType{get;set;}="";public string ReferenceId{get;set;}="";public string Description{get;set;}="";public DateTimeOffset OccurredAt{get;set;}=DateTimeOffset.UtcNow;}
public sealed class LedgerEntry:EntityBase{public Guid EntryId{get;set;}public long WalletInternalId{get;set;}public long TransactionInternalId{get;set;}public string Direction{get;set;}="Credit";public decimal Amount{get;set;}}
public sealed class WalletDbContext(DbContextOptions<WalletDbContext>o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<WalletAccount>Wallets=>Set<WalletAccount>();public DbSet<LedgerTransaction>Transactions=>Set<LedgerTransaction>();public DbSet<LedgerEntry>Entries=>Set<LedgerEntry>();protected override void OnModelCreating(ModelBuilder m){m.HasDefaultSchema("wallet");ConfigureEntity(m.Entity<WalletAccount>());ConfigureEntity(m.Entity<LedgerTransaction>());ConfigureEntity(m.Entity<LedgerEntry>());m.Entity<WalletAccount>().HasIndex(x=>x.WalletId).IsUnique();m.Entity<WalletAccount>().HasIndex(x=>x.FundedAccountInternalId).IsUnique().HasFilter("is_deleted=false");m.Entity<LedgerEntry>().Property(x=>x.Amount).HasPrecision(20,4);}}
public sealed class WalletService(WalletDbContext db):IWalletReader,IWalletLedger{public async Task<WalletSnapshot?> GetByAccountAsync(long id,CancellationToken ct)=>await db.Wallets.AsNoTracking().Where(x=>x.FundedAccountInternalId==id).Select(x=>new WalletSnapshot(x.Id,x.WalletId,x.FundedAccountInternalId,x.CachedAvailableBalance,x.CachedWithdrawableBalance)).SingleOrDefaultAsync(ct);public async Task CreditProfitAsync(long id,decimal amount,string rt,string rid,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);var w=await db.Wallets.SingleAsync(x=>x.FundedAccountInternalId==id,ct);var t=new LedgerTransaction{TransactionId=MyFundex.BuildingBlocks.Ids.Uuid7.NewGuid(),TransactionType="ProfitCredit",ReferenceType=rt,ReferenceId=rid,Description="Realized trader profit"};db.Add(t);await db.SaveChangesAsync(ct);db.Add(new LedgerEntry{EntryId=MyFundex.BuildingBlocks.Ids.Uuid7.NewGuid(),WalletInternalId=w.Id,TransactionInternalId=t.Id,Direction="Credit",Amount=amount});w.CachedAvailableBalance+=amount;w.CachedWithdrawableBalance+=amount;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}}
public static class WalletModule{public static IServiceCollection AddWalletModule(this IServiceCollection s,string cs){s.AddDbContext<WalletDbContext>(o=>o.UseNpgsql(cs));s.AddScoped<WalletService>();s.AddScoped<IWalletReader>(sp=>sp.GetRequiredService<WalletService>());s.AddScoped<IWalletLedger>(sp=>sp.GetRequiredService<WalletService>());return s;}}
